const protectionCases={
 'Buffer Overflow':'Allocation exhaustion alone is not a write beyond buffer bounds; code execution is a possible consequence, not a demonstrated exploit.',
 'Race Condition':'Concurrent withdrawal events alone do not identify a check/use race; the draft explicitly stipulates the checked balance, intervening state change and stale use.',
 'Side-Loading':'An off-store distribution path can be legitimate developer/enterprise delivery; the retained malicious APK example is one case, not every sideload.',
 Ransomware:'A payment demand does not end denial of access; payment is not a recovery guarantee.',
 'Rainbow Table':'A complete hash dictionary is not proof of rainbow-chain reconstruction; compatible hash/table assumptions and candidate verification remain necessary.',
 CTF:'Naming a challenge format does not establish training effectiveness, assessed mastery, governance or privacy/compliance placement.',
 ISP:'Naming a connectivity provider does not establish supplier assurance, service obligations, resilience or canonical governance scope.',
 'MOA / MOU':'The title and study grouping do not settle commitments or universal legal force; actual issuing usage and terms remain relevant.',
 OID:'An identifier is not proof of trust, security authority, certificate validation or governance placement.',
 PHI:'Identifiability plus health content alone does not establish HIPAA scope; the prior candidate includes covered-entity/business-associate context and exclusions without classifying real data.',
 'CIO / CSO':'Titles and scope vary; CSO is not automatically renamed CISO or given a universal information/physical-security responsibility map.',
 SOC:'A clear operations-center meaning does not resolve the shared support node with chip SoC and the operations/assurance glossary.',
 Phishing:'Mass distribution is one example; the umbrella concept does not require many recipients or make every targeted subtype an independent assessed family.',
 Tailgating:'Lack of separately presented credentials does not make an authorized escorted visitor an attacker; unauthorized following-entry is the scoped case.',
 DKIM:'A valid signing-domain signature over covered content does not authenticate the visible From author, establish truth or prove message safety.',
 TAXII:'A meaning-only edit cannot repair an expansion shown on acronym recall; the prior TAXII2.1 expansion correction changes the source-factory ID and remains outside this slice.',
};
